    {"name": "edit", "arguments": {"path": "src/cache.js", "range": "1te-77wi", "new": "// The cache. README.md has the contract.\n//\n// Entries live in a Map in least-recently-used order.\n\nexport class TtlCache {\n  constructor({ capacity, ttl = 0, clock = Date.now, onEvict } = {}) {\n    if (!Number.isInteger(capacity) || capacity <= 0) throw new RangeError('capacity must be a positive integer');\n    this._validateTtl(ttl);\n    this._capacity = capacity; this._ttl = ttl; this._clock = clock; this._onEvict = onEvict;\n    this._entries = new Map();\n    this._stats = { hits: 0, misses: 0, expired: 0, evicted: 0 };\n  }\n\n  _validateTtl(ttl) {\n    if (typeof ttl !== 'number' || !Number.isFinite(ttl) || ttl < 0) throw new RangeError('ttl must be a finite non-negative number');\n  }\n\n  _remove(key, reason) {\n    const entry = this._entries.get(key); this._entries.delete(key);\n    if (reason === 'expired') this._stats.expired++;\n    if (reason === 'capacity') this._stats.evicted++;\n    if (this._onEvict) this._onEvict(key, entry.value, reason);\n  }\n\n  _prune() {\n    let removed = 0;\n    for (const [key, entry] of this._entries) {\n      if (this._clock() >= entry.expires) { this._remove(key, 'expired'); removed++; }\n    }\n    return removed;\n  }\n\n  _ttlFor(options) {\n    const life = options && Object.hasOwn(options, 'ttl') ? options.ttl : this._ttl;\n    this._validateTtl(life); return life;\n  }\n\n  _expiry(ttl) { return ttl === 0 ? Infinity : this._clock() + ttl; }\n\n  set(key, value, options = {}) {\n    this._prune(); const expires = this._expiry(this._ttlFor(options));\n    if (this._entries.has(key)) this._entries.delete(key);\n    else if (this._entries.size >= this._capacity) this._remove(this._entries.keys().next().value, 'capacity');\n    this._entries.set(key, { value, expires }); return this;\n  }\n\n  get(key) {\n    this._prune(); const entry = this._entries.get(key);\n    if (!entry) { this._stats.misses++; return undefined; }\n    this._stats.hits++; this._entries.delete(key); this._entries.set(key, entry); return entry.value;\n  }\n\n  peek(key) { this._prune(); return this._entries.get(key)?.value; }\n  has(key) { this._prune(); return this._entries.has(key); }\n\n  touch(key, options = {}) {\n    this._prune(); const entry = this._entries.get(key); const expires = this._expiry(this._ttlFor(options));\n    if (!entry) return false;\n    this._entries.delete(key); this._entries.set(key, { value: entry.value, expires }); return true;\n  }\n\n  delete(key) {\n    this._prune(); if (!this._entries.has(key)) return false; this._remove(key, 'deleted'); return true;\n  }\n\n  clear() { this._prune(); for (const key of [...this._entries.keys()]) this._remove(key, 'cleared'); }\n  prune() { return this._prune(); }\n  get size() { this._prune(); return this._entries.size; }\n  get stats() { this._prune(); return { ...this._stats }; }\n  keys() { this._prune(); return [...this._entries.keys()].reverse(); }\n}\n"}},
